const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s);let expanded=false,planning=false,day=0,comparing=false;const ns='http://www.w3.org/2000/svg';let toastTimer;
const units=[];for(let i=0;i<120;i++){let r=Math.floor(i/12),c=i%12,x=490+(c-r)*24,y=254+(c+r)*13.8;const g=document.createElementNS(ns,'g');g.classList.add('unit');const polys=[`${x},${y-15} ${x+20},${y-3.5} ${x},${y+8} ${x-20},${y-3.5}`,`${x-20},${y-3.5} ${x},${y+8} ${x},${y+28} ${x-20},${y+16.5}`,`${x},${y+8} ${x+20},${y-3.5} ${x+20},${y+16.5} ${x},${y+28}`];polys.forEach(p=>{const poly=document.createElementNS(ns,'polygon');poly.setAttribute('points',p);g.append(poly)});$('#units').append(g);units.push(g)}
function protectedStock(){return $('#preserve').checked}function firstQty(){return protectedStock()?80:104}function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5000)}
function paint(){const split=planning&&!comparing,first=split?firstQty():80;units.forEach((g,i)=>{const ready=i<80,reserved=split&&!protectedStock()&&i>=80&&i<104,waiting=i>=first;let colors=ready?['#c7e9cf','#507b63','#7ca68a']:reserved?['#c4ace9','#665481','#8a73aa']:['#bd996e','#574b36','#826a4b'];let tx=0,ty=0,opacity=1;if(expanded&&!split&&i>=80){tx=55;ty=-55}if(split){if(!waiting){tx=-52;ty=25}else{tx=115;ty=-90}}if(day>=2&&split&&i<first){tx-=25;ty-=35;opacity=.45}if(day>=6&&waiting){colors=['#d4e5c9','#638367','#92ac8c'];ty+=35}if(day===8){opacity=.65}if(!expanded&&i>=80){colors=['#778078','#303b33','#47564a'];opacity=.5}g.style.transform=`translate(${tx}px,${ty}px)`;g.style.opacity=opacity;[...g.children].forEach((p,j)=>{p.setAttribute('fill',colors[j]);p.setAttribute('stroke',ready?'#d9fce020':'#ffddaa25');p.setAttribute('stroke-width','.7')})});$('#sculpture').setAttribute('aria-label',split?`Split plan: ${first} bikes deliver September 8, ${120-first} September 14. ${protectedStock()?'Other reservation protected.':'24 reserved bikes diverted.'}`:'Order of 120 bikes: 80 available, 40 incoming September 12.');$('#legend-first').textContent=split?`${first} ${day>=2?'delivered Sept 8':'in first shipment'}`:'80 available';$('#legend-second').textContent=split?`${120-first} ${day>=8?'delivered Sept 14':'in second shipment'}`:day>=6?'40 arrived Sept 12':'40 waiting';$('#future-label').textContent=day||planning?'MODELED FUTURE · MOCK ASSUMPTIONS':'OBSERVED STOCK · MOCK SNAPSHOT';}
function unfold(){if(expanded)return;expanded=true;document.body.classList.add('expanded');$$('.anchor').forEach(e=>e.hidden=false);$('#order-target').disabled=true;$('#headline').innerHTML='80 ready.<br><em>40 missing.</em><br>One constraint.';$('#narrative').textContent='The next 40 bikes reach Seattle on September 12. Two days in transit puts the complete order four days late.';$('#primary').innerHTML='Rehearse a split shipment <span>↗</span>';$('#step').textContent='02 — THE DEPENDENCIES';$('#insight-copy').textContent='Another 24 bikes exist, but they are already promised to Summit Sports.';paint()}
function plan(){unfold();planning=true;comparing=false;document.body.classList.add('planning');$('#headline').innerHTML='Keep more<br><em>of the promise.</em>';$('#narrative').textContent='Ship available bikes now. See what changes for Alpine—and for the customer beside it.';$('#back').hidden=false;$('#rehearsal').hidden=false;$('#step').textContent='03 — REHEARSE A POSSIBLE FUTURE';updatePlan();}
function updatePlan(){$('#review').disabled=false;$('#review').textContent='Review this proposal ↗';$('#first-count').textContent=firstQty();$('#second-count').textContent=120-firstQty();$('#consequence').textContent=protectedStock()?'Summit’s reservation stays intact. Alpine’s remaining 40 bikes arrive four days after the original promise.':'Alpine gets 104 bikes early. Summit loses all 24 reserved bikes and its September 9 promise is now at risk.';$('#consequence').style.color=protectedStock()?'':'var(--amber)';$('#plan-name').textContent=protectedStock()?'Split · reservation protected':'Split · another promise at risk';updateTime()}
$('#primary').onclick=()=>expanded?plan():unfold();$('#order-target').onclick=unfold;$('#split').onclick=plan;$('#preserve').onchange=()=>{$('#step').textContent='03 — REHEARSE A POSSIBLE FUTURE';updatePlan()};
function reset(){expanded=false;planning=false;day=0;comparing=false;document.body.classList.remove('expanded','planning');$('#time').value=0;$('#preserve').checked=true;$('#headline').innerHTML='A promise.<br><em>120 bikes.</em><br>Four days.';$('#narrative').textContent='Alpine Cycle needs its next collection by September 10. Something in the chain has moved.';$('#primary').innerHTML='Step inside the order <span>↗</span>';$('#step').textContent='01 — THE COMMITMENT';$('#back').hidden=true;$('#rehearsal').hidden=true;$$('.anchor').forEach(e=>e.hidden=true);$('#order-target').disabled=false;$('#insight-copy').textContent='Stock on hand is not the same as stock you can promise.';updateTime()}
$('#reset').onclick=reset;$('#back').onclick=()=>{planning=false;document.body.classList.remove('planning');expanded=false;$('#rehearsal').hidden=true;$('#back').hidden=true;unfold();updateTime()};
function updateTime(){const labels=['Today','Preparing','First split delivery','Summit’s promise','Alpine’s promise','Promise missed','Incoming stock arrives','In transit','Final delivery'];$('#date-label').innerHTML=`September ${6+day} <span>· ${labels[day]}</span>`;$('#day-count').textContent=`DAY 0${day}`;$('#time-caption').textContent=day===0?'Pull time forward. Watch the constraint become visible.':day<4?planning?`${firstQty()} bikes can arrive September 8 in this proposal.`:'The full order is waiting for the incoming shipment.':day<6?planning?`${120-firstQty()} Alpine bikes are still outstanding.`:'September 10 passes. All 120 bikes are still waiting.':day<8?'Incoming stock has arrived. Allow two days for delivery.':'Alpine receives the remaining bikes on September 14.';paint()}
$('#time').oninput=e=>{day=Number(e.target.value);unfold();updateTime()};
const records={stock:{title:'Ready does not mean free.',copy:'Seattle has 104 Mountain-200 bikes on hand. Only 80 are unreserved and available for Alpine.',rows:[['Inventory snapshot','INV-SEA-200'],['Physical quantity','104 bikes'],['Reserved for Summit','24 bikes'],['Available to Alpine','80 bikes']]},shipment:{title:'A six-day gap.',copy:'An inbound shipment arrives September 12. With two days of outbound transit, those bikes reach Alpine on September 14.',rows:[['Incoming purchase order','PO-00816'],['Quantity','40 bikes'],['Warehouse arrival','September 12'],['Customer arrival','September 14']]},reserved:{title:'Someone else is counting on them.',copy:'Summit Sports has an existing reservation for all 24 bikes. Diverting them helps Alpine but puts Summit’s promise at risk.',rows:[['Customer','Summit Sports'],['Order','SO-71931'],['Reserved quantity','24 bikes'],['Promised delivery','September 9']]}};
function rows(target,data){$(target).replaceChildren(...data.map(([key,value])=>{let row=document.createElement('div');row.className='row';let k=document.createElement('span'),v=document.createElement('strong');k.textContent=key;v.textContent=value;row.append(k,v);return row}))}
$$('[data-evidence]').forEach(b=>b.onclick=()=>{const r=records[b.dataset.evidence];$('#evidence-title').textContent=r.title;$('#evidence-copy').textContent=r.copy;rows('#evidence-rows',r.rows);$('#evidence').showModal()});$$('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.onclick=e=>{if(e.target===d){let r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});
$('#review').onclick=()=>{$('#review-copy').textContent=protectedStock()?'Alpine receives a partial delivery early. The remaining delivery date must be agreed with the customer.':"This version reallocates another customer’s stock. Both customer commitments need review.";rows('#review-rows',[['Alpine · September 8',`${firstQty()} bikes`],['Alpine · September 14',`${120-firstQty()} bikes`],['Summit reservation',protectedStock()?'24 preserved':'24 diverted'],['Additional freight','$480'],['Order value','$108,000']]);$('#approval').showModal()};$('#approve').onclick=()=>{$('#approval').close();$('#review').textContent='✓ Mock proposal approved';$('#review').disabled=true;$('#step').textContent='04 — MOCK APPROVAL RECORDED';toast('Mock proposal approved. No real order or reservation was changed.')};
const compare=$('#compare');function startCompare(){comparing=true;compare.textContent='Original: all 120 arrive September 14';paint()}function endCompare(){if(!comparing)return;comparing=false;compare.textContent='Hold to see original plan';paint()}compare.onpointerdown=e=>{compare.setPointerCapture(e.pointerId);startCompare()};compare.onpointerup=compare.onpointercancel=compare.onlostpointercapture=endCompare;compare.onkeydown=e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();startCompare()}};compare.onkeyup=e=>{if(e.key===' '||e.key==='Enter')endCompare()};compare.onblur=endCompare;
$('#intent').onsubmit=e=>{e.preventDefault();let text=$('#thought').value.toLowerCase();$('#thought').value='';if(/ship|split|now|early/.test(text)){plan();toast('Rehearsing a split shipment. Change the reservation to explore its consequence.')}else if(/protect|preserve|summit|reserv/.test(text)){plan();$('#preserve').checked=true;updatePlan();toast('Summit’s 24 reserved bikes stay protected.')}else if(/why|late|stock|missing/.test(text)){unfold();$('[data-evidence="shipment"]').click()}else if(/reset|restart/.test(text)){reset()}else{toast('This scripted sketch supports “ship what we have now”, “protect Summit”, and “why is it late?”.')}};
let paused=matchMedia('(prefers-reduced-motion:reduce)').matches;function motion(){document.body.classList.toggle('paused',paused);$('#motion').textContent=paused?'Resume motion':'Pause motion';$('#motion').setAttribute('aria-pressed',paused)}$('#motion').onclick=()=>{paused=!paused;motion()};motion();paint();
